using CK.Core;
using System;
using System.Collections.Generic;
using System.Linq;

namespace CK.AppIdentity;

/// <summary>
/// The configuration values burnt in the generated code by the build: the values that a <c>"$LOCK"</c> (or a package's
/// restriction) restricts to <see cref="ConfigurationLevel.Compile"/>. The host adds them after its other configuration
/// sources (CK.AppHost): nothing outside the build can change them.
/// <para>
/// Generated by CK.AppIdentity.Engine from the App's BinPath (its CompiledValues and CompiledLocks).
/// </para>
/// </summary>
[ContextBoundDelegation( "CK.Setup.CompiledConfigurationImpl, CK.AppIdentity.Engine" )]
public abstract class CompiledConfiguration : IRealObject
{
    IReadOnlyList<string[]>? _locks;

    /// <summary>
    /// Gets the burnt values by their path in the host's configuration (case insensitive). A null value burns an absent
    /// value: whatever the other sources say, it is null.
    /// </summary>
    public abstract IReadOnlyDictionary<string, string?> Values { get; }

    /// <summary>
    /// Gets the patterns of the paths of the host's configuration that the build locks: ':' separated, a whole segment
    /// <c>*</c> matches a segment that is not an integer, <c>[*]</c> an integer one; a pattern covers the paths whose
    /// first segments it matches. A value they cover that is not one of the <see cref="Values"/> is ignored.
    /// </summary>
    public abstract IReadOnlyList<string> Locks { get; }

    /// <summary>
    /// Gets whether a path of the host's configuration is covered by one of the <see cref="Locks"/>.
    /// </summary>
    /// <param name="path">The path (':' separated).</param>
    /// <returns>True when the build locks it.</returns>
    public bool IsLocked( string path )
    {
        _locks ??= Locks.Select( l => l.Split( ':' ) ).ToArray();
        var segments = path.Split( ':' );
        return _locks.Any( l => Covers( l, segments ) );
    }

    // The matching of CK.Setup.ConfigurationPathPattern (the engine model is not referenced at run time).
    static bool Covers( string[] pattern, string[] segments )
    {
        if( segments.Length < pattern.Length ) return false;
        for( int i = 0; i < pattern.Length; ++i )
        {
            var p = pattern[i];
            var s = segments[i];
            bool match = p switch
            {
                "*" => !IsIndex( s ),
                "[*]" => IsIndex( s ),
                _ => p.Equals( s, StringComparison.OrdinalIgnoreCase )
            };
            if( !match ) return false;
        }
        return true;

        static bool IsIndex( string s ) => s.Length > 0 && s.All( c => c is >= '0' and <= '9' );
    }
}
